def find_length(string, n=None):
    """Write a function to find the maximum difference between the number of 0s and number of 1s in any sub-string of the given binary string."""
    if string is None:
        return -1
    if n is None:
        n = len(string)
    if n <= 0 or len(string) == 0:
        return -1

    # Transform each binary digit arithmetically: a digit d contributes
    # 1 - 2 * d, then the answer is the maximum sub-array sum (Kadane's
    # algorithm) over non-empty sub-strings. This naturally yields -1
    # when the string contains only ones.
    current = 0
    best = float("-inf")
    for char in string[:n]:
        value = 1 - 2 * int(char)
        current = max(value, current + value)
        best = max(best, current)
    return int(best) if best != float("-inf") else -1
